   484  // On success, returns the tile list OBU size. On failure, sets
   485  // pbi->common.error.error_code and returns 0.
   486  static uint32_t read_and_decode_one_tile_list(AV1Decoder *pbi,
   487                                                struct aom_read_bit_buffer *rb,
   488                                                const uint8_t *data,
   489                                                const uint8_t *data_end,
   490                                                const uint8_t **p_data_end,
   491                                                int *frame_decoding_finished) {
   492    AV1_COMMON *const cm = &pbi->common;
   493    uint32_t tile_list_payload_size = 0;
   494    const int num_tiles = cm->tiles.cols * cm->tiles.rows;
   495    const int start_tile = 0;
   496    const int end_tile = num_tiles - 1;
   497    int i = 0;
   498
   499    // Process the tile list info.
   500    pbi->output_frame_width_in_tiles_minus_1 = aom_rb_read_literal(rb, 8);
   501    pbi->output_frame_height_in_tiles_minus_1 = aom_rb_read_literal(rb, 8);
   502    pbi->tile_count_minus_1 = aom_rb_read_literal(rb, 16);
   503    if (pbi->tile_count_minus_1 > MAX_TILES - 1) {
   504      cm->error.error_code = AOM_CODEC_CORRUPT_FRAME;
   505      return 0;
   506    }
   507
   508    // Allocate output frame buffer for the tile list.
   509    alloc_tile_list_buffer(pbi);
   510
   511    uint32_t tile_list_info_bytes = 4;
   512    tile_list_payload_size += tile_list_info_bytes;
   513    data += tile_list_info_bytes;
   514
   515    int tile_idx = 0;
   516    for (i = 0; i <= pbi->tile_count_minus_1; i++) {
   517      // Process 1 tile.
   518      // Reset the bit reader.
   519      rb->bit_offset = 0;
   520      rb->bit_buffer = data;
   521
   522      // Read out the tile info.
   523      uint32_t tile_info_bytes = 5;
   524      // Set reference for each tile.
   525      int ref_idx = aom_rb_read_literal(rb, 8);
   526      if (ref_idx >= MAX_EXTERNAL_REFERENCES) {
   527        cm->error.error_code = AOM_CODEC_CORRUPT_FRAME;
   528        return 0;
   529      }
   530      av1_set_reference_dec(cm, cm->remapped_ref_idx[0], 1,
   531                            &pbi->ext_refs.refs[ref_idx]);
   532
   533      pbi->dec_tile_row = aom_rb_read_literal(rb, 8);
   534      pbi->dec_tile_col = aom_rb_read_literal(rb, 8);
   535      if (pbi->dec_tile_row < 0 || pbi->dec_tile_col < 0 ||
   536          pbi->dec_tile_row >= cm->tiles.rows ||
   537          pbi->dec_tile_col >= cm->tiles.cols) {
   538        cm->error.error_code = AOM_CODEC_CORRUPT_FRAME;
   539        return 0;
   540      }
   541
   542      pbi->coded_tile_data_size = aom_rb_read_literal(rb, 16) + 1;
   543      data += tile_info_bytes;
   544      if ((size_t)(data_end - data) < pbi->coded_tile_data_size) {
   545        cm->error.error_code = AOM_CODEC_CORRUPT_FRAME;
   546        return 0;
   547      }
   548
   549      av1_decode_tg_tiles_and_wrapup(pbi, data, data + pbi->coded_tile_data_size,
   550                                     p_data_end, start_tile, end_tile, 0);
   551      uint32_t tile_payload_size = (uint32_t)(*p_data_end - data);
   552
   553      tile_list_payload_size += tile_info_bytes + tile_payload_size;
   554
   555      // Update data ptr for next tile decoding.
   556      data = *p_data_end;
   557      assert(data <= data_end);
   558
   559      // Copy the decoded tile to the tile list output buffer.
   560      copy_decoded_tile_to_tile_list_buffer(pbi, tile_idx);
